description:
Design a parameterized synchronous memory module with read and write capabilities. This dual-port memory allows external data to be written to specific addresses indicated by the `addr` input when the corresponding write enable signals in `wen` are asserted. The output `dout` reflects the value stored at the specified address when the module is enabled (`en`). The memory organization is defined by address width (AW) and data width (DW), supporting multiple bytes depending on the width enabled by `WED`. The module is structured to ensure data is read at the rising edge of the clock, with simultaneous write operations being handled for each byte of the specified data input.
module top_module(

   dout,

   clk, en, wen, addr, din
   );

code:
module top_module(

   dout,

   clk, en, wen, addr, din
   );parameter AW      = 14;   
   parameter DW      = 32;
   parameter WED     = DW/8; 
   parameter MD      = 1<<AW;


   input               clk; 
   input               en;  
   input [WED-1:0]     wen; 
   input [AW-1:0]      addr;
   input [DW-1:0]      din; 
   output [DW-1:0]     dout;

   reg [DW-1:0]        ram    [MD-1:0];  
   reg [DW-1:0]        rd_data;
   reg [DW-1:0]        dout;


   always @ (posedge clk)
     if(en)       
       dout[DW-1:0] <= ram[addr[AW-1:0]];


   generate
      genvar 	     i;
      for (i = 0; i < WED; i = i+1) begin: gen_ram
	 always @(posedge clk)
           begin  
              if (wen[i] & en) 
                ram[addr[AW-1:0]][(i+1)*8-1:i*8] <= din[(i+1)*8-1:i*8];
           end
      end
   endgenerate

endmodule

