module top_module(
    input clk,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder
);reg [15:0] dividend_reg;
reg [15:0] divisor_reg;
reg [15:0] quotient_reg;
reg [15:0] remainder_reg;

reg [3:0] count;

always @(*) begin
    dividend_reg = dividend;
    divisor_reg = divisor;
end

always @(posedge clk) begin
    if (count == 0) begin
        quotient_reg <= 0;
        remainder_reg <= dividend_reg;
    end else begin
        if (remainder_reg[15] == 1) begin
            remainder_reg <= (remainder_reg << 1) | 1;
        end else begin
            remainder_reg <= remainder_reg << 1;
        end
        quotient_reg <= quotient_reg << 1;
        if (remainder_reg >= divisor_reg) begin
            remainder_reg <= remainder_reg - divisor_reg;
            quotient_reg <= quotient_reg | 1;
        end
    end
    count <= count + 1;
end

assign quotient = quotient_reg;
assign remainder = remainder_reg;

endmodule

