description:
Design a two-bit equality comparator that outputs a HIGH signal when the two 2-bit inputs, A and B, are equal. The module uses XOR gates to compare each corresponding bit of the inputs and an AND gate to determine if both bits are equal, resulting in an output of EQ being HIGH only when both bits in A and B match.
module top_module(
    input [1:0] A,
    input [1:0] B,
    output EQ
);

code:
module top_module(
    input [1:0] A,
    input [1:0] B,
    output EQ
);wire eq1, eq2, eq3;

    // Check if A[1] == B[1]
    xor x1(eq1, A[1], B[1]);

    // Check if A[0] == B[0]
    xor x2(eq2, A[0], B[0]);

    // Check if A == B
    and a1(eq3, eq1, eq2);

    // Set output EQ to 1 if A == B, 0 otherwise
    assign EQ = eq3;

endmodule

