		end
		Trasmitir:begin
			if(EndTras) begin
				if(ParityCoherente)state=NewS;
				else state=Sleep;
			end
			else state=Wait ;
		end
		Wait:begin
			if(NewDataKB) state=Trasmitir;
			else state=Wait;
		end
		NewS: state=Sleep;
		default: state = Sleep ;
		endcase
	end
end
always @(state) begin
  case(state)
    Sleep :begin
		Load=0;
		Borrar=1;
		New=0;
		end
    Wait :begin
		Load=0;
		Borrar=0;
		New=0;
		end
    Trasmitir:begin
		Load=1;
		Borrar=0;
		New=0;
		end
    NewS:begin
		Load=0;
		Borrar=0;
		New=1;
		end
    default:
      begin
		Load=0;
		Borrar=1;
		New=0;
       end
  endcase
