always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        write_ptr <= 0;
        read_ptr <= 0;
    end else begin
        if (write_en) begin
            ram[write_addr] <= write_data;
            write_ptr <= write_ptr + 1;
        end
        if (read_en) begin
            ram_out1 <= ram[read_addr];
            read_ptr <= read_ptr + 1;
        end
    end
end

