module top_module(clk, reset, x, y);input        clk;
  input        reset;
  input  [31:0] x;
  output [31:0] y;
  reg    [31:0] y;
  reg    [31:0] tap0, tap1, tap2, tap3, tap4, tap5;

  always @(posedge clk)  
  begin : p1
    if (reset == 1) begin
            tap0 <= 0;
            tap1 <= 0;
            tap2 <= 0;
            tap3 <= 0;
            tap4 <= 0;
            tap5 <= 0;
        end
    else begin
        y <= tap0 + tap1*2 + tap2*3 + tap3*3 + tap4*2 + tap5;

        tap5 <= tap4;
        tap4 <= tap3;
        tap3 <= tap2;  
        tap2 <= tap1;
        tap1 <= tap0;
        tap0 <= x;   
    end
  end

endmodule

