	output reg memRead,
	output reg memWrite,
	output reg branch,
	output reg [1:0] aluOp,
	output reg jump
	);always @(opCode)
	 begin
	 case (opCode)
	       6'b000010:

			 begin
			     regDst = 0;
				  aluSrc = 0;
				  memToReg = 0;
				  regWrite = 0;
				  memRead = 0;
				  memWrite = 0;
				  branch =0;
				  aluOp = 2'b00;
				  jump = 1;
