			     regDst = 1;
				  aluSrc = 0;
				  memToReg = 0;
				  regWrite = 1;
				  memRead = 0;
				  memWrite = 0;
				  branch = 0;
				  aluOp =  2'b10;   

				  jump = 0;
			 end
			 6'b100011:

			 begin
			     regDst = 0;
				  aluSrc = 1;
				  memToReg = 1;
				  regWrite = 1;
				  memRead = 1;
				  memWrite = 0;
				  branch = 0;
				  aluOp =  2'b00;   
				  jump = 0;
			 end
			 6'b101011:

			 begin
			     regDst = 1; 
				  aluSrc = 1;
				  memToReg = 1; 
				  regWrite = 0;
				  memRead = 0;
				  memWrite = 1;
				  branch = 0;
				  aluOp =  2'b00;   
				  jump = 0;
			 end
			 6'b000100:

			 begin
			     regDst = 0;  
				  aluSrc = 0;
				  memToReg = 0;  
				  regWrite = 0;
				  memRead = 0;
				  memWrite = 0;
				  branch = 1;
				  aluOp =  2'b01;   
				  jump = 0;
			 end
			 default:
			 begin
			     regDst = 0;
				  aluSrc = 0;
				  memToReg = 0;
				  regWrite = 0;
				  memRead = 0;
				  memWrite = 0;
				  branch = 0;
				  aluOp =  2'b00;   
				  jump = 0;
			 end
		endcase
		end

endmodule

