module top_module(clk, rst, set, d, q);input clk, rst, set, d;
output q;

reg q;

always @(posedge clk, negedge rst, negedge set) begin
    if (rst) begin
        q <= 0;
    end else if (set) begin
        q <= 1;
    end else begin
        q <= d;
    end
end

endmodule

module shift_register(
   input                clk,
   input                rst_n,
   input                load,
   input  [7:0]         D,

   output reg [7:0]     Q
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) Q <= 8'b0;
        else if (load) Q <= D;
        else Q <= {1'b0, Q[7:1]};
    end
endmodule

