    input wire [15:0] wd,
    output reg [15:0] rq
);parameter AWIDTH = 10;
    parameter DWIDTH = 16;

    reg [DWIDTH-1:0] mem [0:(1<<AWIDTH)-1];

    always @(posedge clk) begin
