	stream_out_data,
	stream_out_startofpacket,
	stream_out_endofpacket,
	stream_out_valid
);parameter CW		= 29;			
parameter DW		= 39;			

parameter COLOR	= 30'd0;		
parameter ALPHA	= 10'd0;		




