module top_module(
  input clk,
  input [18:0] cpu_d_address,
  input cpu_d_read,
  input [31:0] cpu_d_readdata,
  input cpu_d_wait,
  input cpu_d_write,
  input [31:0] cpu_d_writedata,
  input jrst_n,
  input [15:0] trc_ctrl,
  output reg [35:0] atm,
  output reg [35:0] dtm
);reg record_load_addr;
  reg record_load_data;
  reg record_store_addr;
  reg record_store_data;

  always @(posedge clk or negedge jrst_n) begin
    if (~jrst_n) begin
      atm <= 0;
      dtm <= 0;
    end else begin
      if (cpu_d_write & ~cpu_d_wait) begin
        if (trc_ctrl[0]) begin
          record_store_addr <= 1;
          atm <= {4'b0101, cpu_d_address};
        end else begin
          record_store_addr <= 0;
          atm <= {4'b0000, cpu_d_address};
        end
        if (trc_ctrl[1]) begin
          record_store_data <= 1;
          dtm <= {4'b0111, cpu_d_writedata};
        end else begin
          record_store_data <= 0;
          dtm <= {4'b0000, cpu_d_writedata};
        end
      end else if (cpu_d_read & ~cpu_d_wait) begin
        if (trc_ctrl[2]) begin
          record_load_addr <= 1;
          atm <= {4'b0100, cpu_d_address};
        end else begin
          record_load_addr <= 0;
          atm <= {4'b0000, cpu_d_address};
        end
        if (trc_ctrl[3]) begin
          record_load_data <= 1;
          dtm <= {4'b0110, cpu_d_readdata};
        end else begin
          record_load_data <= 0;
          dtm <= {4'b0000, cpu_d_readdata};
        end
      end else begin
        atm <= 0;
        dtm <= 0;
      end
    end
  end

endmodule

