module top_module(
    input clk,                  // Clock signal
    input [7:0] in,             // 8-bit input vector
    input select,               // Select input to choose between module outputs
    output [7:0] out            // 8-bit final output
);// First module - Reverse bit order using shift register
    reg [7:0] shift_reg;
    always @ (posedge clk) begin
        shift_reg <= {shift_reg[6:0], in[7]};
    end

    // Second module - 3-bit shift register using D flip-flops and multiplexer
    reg [2:0] shift_reg_3;
    reg serial_out;
    always @ (posedge clk) begin
        shift_reg_3 <= {shift_reg_3[1:0], in[0]};
        serial_out <= select ? shift_reg[0] : shift_reg_3[0];
    end

    // Functional module - Bitwise AND operation to produce final output
    assign out = select ? shift_reg & in : {3'b0, serial_out, shift_reg_3};

endmodule

