module top_module(DataIO, Reset, Push, Pop, 
              SP, Full, Empty, Err);inout [3:0] DataIO; 
  input Push, Pop, Reset;
  output Full, Empty, Err;
  output [2:0] SP;


  reg Full, Empty, Err;
  reg [2:0] SP;
  reg [3:0] Stack [7:0];
  reg [3:0] DataR;


  wire [3:0]  #(0) DataIO = DataR;



  always @(posedge Push or posedge Pop or posedge Reset) 
  begin

    if (Push == 1)
    begin

      if (Empty == 1)
      begin
        Stack[SP] = DataIO;
        Empty = 0;
        if (Err == 1)
          Err = 0;
      end
      else if (Full == 1) 
      begin
        Stack[SP] = DataIO;
        Err = 1;
      end
      else
      begin
        SP = SP + 1;
        Stack[SP] = DataIO;
        if (SP == 3'b111)
          Full = 1;
      end
    end


    if (Pop == 1) 
    begin             
      if ((SP == 3'b000) && (Empty != 1))
      begin
        DataR = Stack[SP];
        Empty = 1;
      end
      else if (Empty == 1) 
      begin
        DataR = Stack[SP];
        Err = 1;
      end
      else
      begin
        DataR = Stack[SP];
        if (SP != 3'b000)
          SP = SP - 1;

        if (Err == 1)  Err = 0;
        if (Full == 1)  Full = 0;
      end
    end


    if (Reset == 1)
    begin
      DataR = 4'bzzzz;
      SP = 3'b0;
      Full = 0;
      Empty = 0;
      Err = 0;
    end

  end


  always @(negedge Pop)
  begin
    DataR = 4'bzzzz;
  end  


endmodule

module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);reg [7:0] data_reg1, data_reg2, data_reg3;
reg [9:0] acc_reg1, acc_reg2, acc_reg3;

reg [1:0] stage;

assign ready_a = (stage == 0) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage <= 0;
        data_reg1 <= 8'b0;
        data_reg2 <= 8'b0;
        data_reg3 <= 8'b0;
        acc_reg1 <= 10'b0;
        acc_reg2 <= 10'b0;
        acc_reg3 <= 10'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        case(stage)
            0: begin
                if (valid_a) begin
                    data_reg1 <= data_in;
                    stage <= 1;
                end
            end
            1: begin
                data_reg2 <= data_reg1;
                acc_reg1 <= {2'b0, data_reg1} + acc_reg1;
                stage <= 2;
            end
            2: begin
                data_reg3 <= data_reg2;
                acc_reg2 <= {2'b0, data_reg2} + acc_reg1;
                stage <= 3;
            end
            3: begin
                acc_reg3 <= {2'b0, data_reg3} + acc_reg2;
                data_out <= acc_reg3;
                valid_b <= 1'b1;
                stage <= 0;
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_b <= 1'b0;
    end
    else begin
        if (valid_b && ready_b) begin
            valid_b <= 1'b0;
        end
    end
end

endmodule

